"""Consolidate retained synthetic evidence; never read or publish private manifests."""
import json
import os
import re
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TEMP = Path(os.environ['TEMP'])

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))

def build():
    current = Path((ROOT/'latest-phase-c2b-evidence.txt').read_text().strip())
    if current.parent.resolve() != TEMP.resolve() or not re.fullmatch(r'GSO_PHASE_C2B_\d{8}_\d{6}', current.name):
        raise RuntimeError('Expected private C2B evidence in TEMP')
    folders = [TEMP/'GSO_PHASE_A_20261017_102501', TEMP/'GSO_PHASE_B_20261017_104116',
               TEMP/'GSO_PHASE_C1_20261017_124045', TEMP/'GSO_PHASE_C2A_20261017_154946', current]
    c1 = read(folders[2]/'c1_evidence_review.json')
    c2 = read(folders[3]/'c2a_evidence_review.json')
    assert c1['passed'] and c2['passed'] and c1['races']==40 and c2['pairs']==64
    for folder, completion, expected in [(folders[2],'c1_completion.json',40),(folders[3],'c2a_completion.json',64)]:
        done=read(folder/completion)
        assert done['complete'] and done['passed']==expected
        gates=list(folder.glob('integrity_*.json'))
        assert len(gates)>=expected+1
        for path in gates:
            gate=read(path)
            assert gate['passed'] and gate['foreign_keys_checked']==57 and sum(gate['violations'].values())==0
    runs=[]
    for users, configured, folder, name, gate in [(1,90,folders[0],'baseline','baseline'),(5,120,folders[0],'five','five'),(10,300,folders[1],'ten','ten'),(15,600,folders[1],'fifteen','fifteen'),(20,120,current,'spike','spike_20')]:
        data=read(folder/(name+'_summary.json')); metrics=data['metrics']
        integrity=read(folder/('integrity_'+gate+'.json'))
        assert integrity['passed'] and integrity['foreign_keys_checked']==57 and sum(integrity['violations'].values())==0
        assert metrics['http_req_failed']['values']['rate']==0 and metrics['http_500']['values']['count']==0 and metrics['unintended_errors']['values']['count']==0
        runs.append(dict(users=users, configured_seconds=configured, actual_seconds=data['state']['testRunDurationMs']/1000,
                         requests=metrics['http_reqs']['values']['count'], requests_per_second=metrics['http_reqs']['values']['rate'],
                         latency_ms=metrics['http_req_duration']['values'],http_failures=metrics['http_req_failed']['values']['passes'],http_500=metrics['http_500']['values']['count'],unintended_errors=metrics['unintended_errors']['values']['count'],integrity='PASS'))
    assert read(current/'spike_execution.json')['exit_code']==0
    rows=[json.loads(x) for x in (current/'telemetry.jsonl').read_text(encoding='utf-8-sig').splitlines() if x.strip()]
    assert rows
    before=read(current/'before_db_status.json');after=read(current/'after_db_status.json')
    telemetry=dict(samples=len(rows),cpu_average_percent=sum(r['cpu_percent'] for r in rows)/len(rows),cpu_peak_percent=max(r['cpu_percent'] for r in rows),minimum_available_ram_gib=min(r['available_ram_bytes'] for r in rows)/1024**3,apache_peak_busy_workers=max(r['BusyWorkers'] for r in rows),apache_peak_working_set_mib=max(r['apache_working_set_bytes'] for r in rows)/1024**2,database_peak_connected=max(r['database']['Threads_connected'] for r in rows),database_peak_running=max(r['database']['Threads_running'] for r in rows),current_lock_waits_peak=max(r['database']['Innodb_row_lock_current_waits'] for r in rows),lock_waits_delta=after['Innodb_row_lock_waits']-before['Innodb_row_lock_waits'],lock_wait_time_ms_delta=after['Innodb_row_lock_time']-before['Innodb_row_lock_time'],aborted_connections_delta=after['Aborted_connects']-before['Aborted_connects'])
    php=(current/'php_error.log').read_text(errors='replace') if (current/'php_error.log').exists() else ''
    apache=(current/'apache_error.log').read_text(errors='replace')
    maria=(current/'mariadb_log_delta.txt').read_text(encoding='utf-8-sig')
    assert not php.strip() and not maria.strip()
    assert not re.search(r'\[(?:[^\]]*:(?:warn|error|crit|alert|emerg))\]',apache,re.I)
    assert not (current/'monitor_errors.log').exists()
    endpoints=Counter();status=Counter();roles=Counter();duration_count=0
    for line in (current/'spike_samples.json').open(encoding='utf-8-sig'):
        entry=json.loads(line)
        if entry.get('type')=='Point' and entry.get('metric')=='http_req_duration':
            tags=entry['data']['tags'];endpoints[tags['name']]+=1;status[tags['status']]+=1;roles[tags['role']]+=1;duration_count+=1
    assert duration_count==runs[-1]['requests'] and len(roles)==5 and endpoints['login_submit']==20
    assert all(endpoints[k]>0 for k in ['borrower_browse','borrower_my_requests','facility_availability','borrower_owned_status','chat_owned_status','chat_availability','gso_dashboard','gso_requests','gso_on_loan','gso_walkin','gso_maintenance','gso_maintenance_history','director_schedule','director_filtered_schedule','mis_dashboard','mis_system_accounts','mis_borrower_accounts'])
    health=read(current/'server_health.private.json');meta=read(current/'run_metadata.json');integrity=read(current/'integrity_spike_20.json')
    assert health['smtp_disabled'] and health['smtp_config_rejected'] and health['local_fallback']
    assert len(list((current/'mail_outbox').glob('*')))==0
    assert len(integrity['table_hashes'])==22 and integrity['schema_changed_tables']==[] and integrity['changed_business_tables']==[]
    evidence=dict(database=meta['database'],checkpoint=meta['checkpoint'],baseline=meta['baseline'],runs=runs,telemetry=telemetry,endpoint_counts=dict(endpoints),role_request_counts=dict(roles),status_counts=dict(status),schema=integrity['schema'],integrity_violations=integrity['violations'],foreign_keys_checked=57,logs='PASS',mail_captures=0,production_changes=False)
    (ROOT/'phase_c2b_summary.json').write_text(json.dumps(evidence,indent=2)+'\n')
    spike=runs[-1];lat=spike['latency_ms'];t=telemetry
    assert lat['p(95)']<=2000, 'Review performance-degradation classification before reporting'
    assert set(status).issubset({'200','302'})
    sections=['# Final concurrency verification report\n\nLocal load workloads at 1, 5, 10 and 15 users passed. The supplementary 20-user spike passed. All 104 recorded race pairs passed their integrity gates. No production changes were required. Results describe the tested local workload only.\n']
    def section(title,text): sections.append('## '+title+'\n\n'+text+'\n')
    section('1. Tested application baseline / checkpoints',f"Production baseline: `{meta['baseline']}`. Phase A assets: `92e0242077675a842420d1def52bff2e883b22f8`; Phase B: `46cb46c90e3b7e24c2171ec6c385e4f97997907b`; C1: `daa9b4860e98fd728c084c5345a7c1ead3d83de3`; C2A/C2B starting checkpoint: `{meta['checkpoint']}`. Initial HEAD matched and working tree was clean. All subsequent changes are test/documentation assets in scripts/load. The C2B runtime was exported with git archive from the production baseline, excluding ignored developer configuration. Earlier reports remain unchanged.")
    section('2. Test machine','Acer Nitro ANV15-41; AMD Ryzen 5 6600H, 6 cores / 12 logical processors; 16 GB installed RAM (15.31 GiB visible); KINGSTON OM8SEP4512Q-AA 512 GB disk; Windows 11 Home Single Language 10.0.26300 build 26300. k6, Apache and MariaDB shared this computer. Detailed current hardware observations remain in private machine.json.')
    section('3. Software environment',f"Apache 2.4.58 Win64; PHP {health['php']}; MariaDB {health['mariadb']}; k6 v2.2.0 (00a9a1b7f5, Go 1.26.5, windows/amd64). Loopback HTTP; Apache capacity 64 workers. No external AI service was used; chatbot checks required deterministic live-data replies.")
    section('4. Isolation methodology',f"Fresh C2B database: `{meta['database']}`. Imported frozen database/schema.sql; no earlier test database or normal database was selected. Runtime credentials have SELECT/INSERT/UPDATE/DELETE rights only on this database. Dedicated Apache bound to 127.0.0.1:8124; separate sessions, upload directory, PHP configuration, logs and mail outbox. Startup disables mail/fsockopen/pfsockopen/stream_socket_client; health checks verified DB identity, schema version and rejected SMTP configuration. No real SMTP; zero C2B outbox messages. All synthetic addresses use example.invalid. Twenty distinct accounts, one cookie jar per VU, real login/CSRF/routes, no production bypass. Owned runtime processes were stopped; DB/evidence retained. No deployment or push.")
    section('5. Frozen schema verification','Before and immediately after C2B: **22 tables, 57 FKs, 104 indexes, 18 UNIQUE, 11 CHECK, 3 generated columns, version 20261010_008**. All 22 normalized SHOW CREATE TABLE hashes match seed; only AUTO_INCREMENT counters are excluded from schema hashes. Frozen schema and ERD files were unchanged throughout these test asset commits.')
    section('6. Phase A summary','PASS. One VU for 90 seconds, then five VUs for 120 seconds, with graceful journey completion. Baseline rotated five accounts sequentially; five-user mix was two Borrowers, one GSO Head, one Director and one MIS. Real login, availability, request and role reads. Both final integrity gates passed; zero HTTP failures, HTTP 500 and unintended errors. Source: [RESULTS.md](RESULTS.md); completed evidence folder GSO_PHASE_A_20261017_102501. Two earlier setup attempts were excluded from reported measurements (startup SMTP guard and harness HTML marker correction), as documented in that report.')
    section('7. Phase B summary','PASS. Ten independent users for 300 seconds; fifteen for 600 seconds; 30-second graceful completion allowed. Ten-user mix: six Borrowers, Head, Staff, Director, MIS. Fifteen: ten Borrowers, Head, two Staff, Director, MIS. Added owned request and deterministic chatbot reads. All final integrity/log gates passed. Source: [PHASE_B_RESULTS.md](PHASE_B_RESULTS.md), GSO_PHASE_B_20261017_104116. These runs were not repeated for consolidation.')
    section('8. Phase C1 summary','PASS: 40 pairs / 80 contenders; all server execution intervals overlapped; server start gaps 0-1106 microseconds. Independent sessions, actual authenticated CSRF POSTs, queued transfers and shared barrier. All 57 FK checks and invariant/log gates passed after each race. Exactly-once settlement and one winning allocation/release were verified from before/after rows and client events. HTTP 200 safe conflict responses were evaluated by database state rather than treated as server errors. Source: [PHASE_C1_RESULTS.md](PHASE_C1_RESULTS.md), [timings](phase_c1_timings.csv), GSO_PHASE_C1_20261017_124045. Prior harness interruptions/corrections are documented there; completed races were preserved.')
    section('9. Phase C2A summary','PASS: 64 pairs / 128 contenders; all server execution intervals overlapped, start gaps 0-1000 microseconds. Damaged/Lost/mixed returns, rescheduling and maintenance were checked after every pair. Lost produced zero repair work orders; Damaged corrective work required GSO Head confirmation. Approval/rejection produced one terminal proposal decision. Start/cancel allowed legitimate ordered transitions while restoring stock once. Preventive generation created one scheduled occurrence without auto-start. Source: [PHASE_C2A_RESULTS.md](PHASE_C2A_RESULTS.md), [timings](phase_c2a_timings.csv), GSO_PHASE_C2A_20261017_154946. No production defect or fix was recorded.')
    section('10. 20-user spike summary',f"PASS. Twenty constant VUs, configured 120 seconds plus 30-second graceful completion; actual k6 duration {spike['actual_seconds']:.3f} seconds. Mix exactly 12 Borrowers, four operational users (Head plus three Staff), two Directors and two MIS. Three additional synthetic accounts extended the Phase B-equivalent fixture before the seed snapshot. Fixture: 96 requests, three facilities, three aggregate resources, two consumable resources and two serialized resources / 24 units. Random initial offset 0-3 seconds; think time 2-4 seconds between reads/chat and 2-5 seconds between journeys. {spike['requests']} HTTP requests, {spike['requests_per_second']:.6f} req/s. Latency ms: min {lat['min']:.4f}, average {lat['avg']:.4f}, median {lat['med']:.4f}, p90 {lat['p(90)']:.4f}, p95 {lat['p(95)']:.4f}, p99 {lat['p(99)']:.4f}, max {lat['max']:.4f}. Zero HTTP failures, HTTP 500, unintended errors; unintended rate 0%. p95 is below 2000 ms; no performance degradation classification. No deliberate races were run during the spike.\n\n{t['samples']} telemetry samples: whole-host CPU average {t['cpu_average_percent']:.2f}%, peak {t['cpu_peak_percent']:.0f}%; minimum available RAM {t['minimum_available_ram_gib']:.3f} GiB; maximum busy Apache workers {t['apache_peak_busy_workers']}/64 (includes status observer); peak aggregate httpd working set {t['apache_peak_working_set_mib']:.2f} MiB (includes normal Apache). Sampled global DB connections peaked at {t['database_peak_connected']}; Threads_running peaked at {t['database_peak_running']}. Current row-lock waits peak {t['current_lock_waits_peak']}; lock-wait count delta {t['lock_waits_delta']}; lock-wait time delta {t['lock_wait_time_ms_delta']} ms; aborted-connect delta {t['aborted_connections_delta']}. MariaDB exposes no Innodb_deadlocks counter here; logs contain no observed deadlock.\n\nEndpoint request counts:\n\n"+'\n'.join(f'- {k}: {v}' for k,v in sorted(endpoints.items())))
    table='Latency is milliseconds; duration is configured / actual seconds including graceful completion. req/s uses actual k6 duration; requests include login and chat where present.\n\n| Users | Duration (s) | Requests | req/s | Avg | Median | p90 | p95 | p99 | Max | HTTP 500 | Integrity |\n|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---|\n'
    for r in runs:
        l=r['latency_ms']; table+=f"| {r['users']} | {r['configured_seconds']} / {r['actual_seconds']:.3f} | {r['requests']} | {r['requests_per_second']:.3f} | "+' | '.join(f'{l[k]:.2f}' for k in ['avg','med','p(90)','p(95)','p(99)','max'])+' | 0 | PASS |\n'
    section('11. Performance table',table+'\nPhase A did not record minimum latency in its summary; no minimum is inferred. Role mixes, run lengths and chat coverage vary, so rows are workload observations rather than a controlled scaling curve.')
    races=[('Facility double approval',5,'One confirmed booking'),('Aggregate oversubscription',5,'4 of 5 issued; losing release unchanged'),('Serialized-unit collision',5,'One open allocation'),('Claim Slip double release',5,'One release and stock deduction'),('Valid vs invalid Claim Slip',5,'Only valid claimant released'),('Duplicate Return submission',5,'One Pending header/detail; stock unchanged'),('Duplicate Return inspection',10,'Five aggregate and five serialized; settlement once'),('Damaged Return',10,'Five aggregate and five serialized; repair hold once; no automatic work order'),('Lost Return',10,'Five aggregate and five serialized; total reduced once; no repair'),('Mixed Return',6,'Three aggregate and three serialized; Good/Damaged/Lost distinct'),('Reschedule proposal',5,'One Pending proposal; parent unchanged'),('Reschedule approval collision',5,'One target booking approved; competing original retained'),('Approve vs reject',5,'One terminal decision: three Approved / two Rejected'),('Maintenance start',5,'Hold and started event once'),('Maintenance complete',10,'Five aggregate and five serialized; confirmed corrective restoration once'),('Conflicting maintenance transition',5,'One cancel before start; four valid start-then-cancel; restoration once'),('Preventive maintenance',3,'One scheduled occurrence per plan/date; no inventory change')]
    assert sum(x[1] for x in races)==104
    section('12. Race-condition table','| Scenario | Iterations / pairs | Result | Integrity violations | Notes |\n|---|---:|---|---:|---|\n'+'\n'.join(f'| {name} | {count} | PASS | 0 | {note} |' for name,count,note in races)+'\n\n104 pairs / 208 contenders total. Scenario results come from retained C1/C2A reviewed evidence; no races were rerun in C2B.')
    section('13. Integrity findings',f"PASS. Immediate C2B read-only transaction audited all 57 FK relationships and {len(integrity['violations'])} aggregate invariant categories: all invalid counts zero. Covered negative/aggregate/consumable/serialized stock, allocation ownership/uniqueness, facility overlap/periods, Claim Slip format/uniqueness/status/no log leakage, quantity/actor/request statuses, verified facility letters, return headers/details/settlement, repair/Lost separation, liabilities, proposal uniqueness/authority/terminal metadata, preventive occurrences/states, completed maintenance/restoration and repair ledger. All business tables matched seed row/hash snapshots; only successful login activity and paired Borrower chat rows were allowed to change. Zero failed logins/unexpected events. Reschedule/return/maintenance tables remained unchanged in this read-oriented spike; their functional mutation evidence comes from C1/C2A. All prior per-run/per-race integrity gates also passed.\n\nC2B audit counts:\n\n"+'\n'.join(f'- {k}: {v}' for k,v in integrity['violations'].items()))
    section('14. Log findings','C2B private PHP/application log: absent/empty; Apache log: normal startup notices only, zero warning/error/critical entries; MariaDB byte-offset delta: empty. Raw k6 samples confirm zero HTTP 500 and expected 200/302 responses. No fatal error, uncaught Throwable, SQLSTATE, deadlock, lock timeout, connection exhaustion, memory exhaustion, maximum execution time or crash observed. No telemetry collection errors. Earlier completed A/B/C2A gates recorded no application errors; C1 recorded one controlled restart stale-PID warning (AH00098), documented separately from request failures. Prior setup/harness corrections are retained in original reports. No global MariaDB logging settings changed; log silence is evidence limited to configured log coverage.')
    section('15. Limitations','One local Windows/XAMPP computer; synthetic data and loopback HTTP; k6 and server share CPU/RAM. No WAN/TLS latency, production hardware/hosting limits, real SMTP delivery, external AI traffic, extended soak or distributed load tested. 20 users ran for two minutes only. These read-oriented load journeys do not measure sustained transactional throughput; critical writes were covered separately by paired races. Telemetry is sampled roughly every five seconds and may miss short peaks; DB status counters are global and include observer/other server activity; Threads_running is not isolated application concurrency. No exposed deadlock counter; no deadlocks observed in configured logs. Maintenance midnight/end-date rollover was not exercised by actual clock passage; preventive work was explicitly started/completed through real routes, as scoped in C2A. Finite races provide evidence for the recorded interleavings, not a proof of every possible schedule. Original private evidence contains credentials/sessions/raw mail and remains outside Git; sanitized summaries and timing CSVs are committed.')
    conclusion='Testing on the local XAMPP environment supports at least 15 concurrent users under the defined workload, with no observed data-integrity violations or unhandled application failures.\n\nA short 20-user spike test also completed successfully, providing additional local headroom evidence.\n\nProduction capacity must be revalidated on the actual target staging or production host because server resources, database configuration, network latency, and hosting limits may differ from the local test environment.'
    classifications='\n\n| Classification | Result |\n|---|---|\n'+''.join(f'| {x} | PASS |\n' for x in ['1-USER BASELINE','5-USER LOAD','10-USER LOAD','15-USER LOAD','20-USER SPIKE','PHASE C1 TRANSACTION RACES','PHASE C2A TRANSACTION RACES','FINAL DATA INTEGRITY'])+'| LOCAL 15-USER CAPACITY | SUPPORTED BY TEST EVIDENCE |\n| LOCAL 20-USER HEADROOM | SUPPORTED BY SPIKE EVIDENCE |'
    section('16. Final conclusion',conclusion+classifications)
    section('17. Recommended thesis wording','Under the defined synthetic workload on the local XAMPP environment, normal concurrent load tests passed through 15 users, and a short 20-user spike provided supplementary headroom evidence. Across 104 deliberately synchronized transaction race pairs, recorded critical operations settled exactly once where required, preserving stock and relational integrity. No facility double booking, stock oversubscription, duplicate serialized allocation, duplicate release or duplicate Return settlement was observed. Lost returns were never routed to repair; Damaged corrective repair required GSO Head confirmation. Frozen schema counts and fingerprints remained unchanged. These findings support the tested local workloads and observed interleavings; they do not establish production capacity. Production capacity must be revalidated on the actual target staging or production host because server resources, database configuration, network latency, and hosting limits may differ from the local test environment.\n\nEvidence index: earlier reports linked above; sanitized C2B metrics/coverage in [phase_c2b_summary.json](phase_c2b_summary.json). Private evidence folders under the operator TEMP directory: '+', '.join('`'+p.name+'`' for p in folders)+'. C2B contains raw k6 samples/summary, seed and post-spike hashes, health/identity, runtime export hash, execution timing, telemetry and logs. Reusable C2B assets: run_phase_c2b.ps1, phase_c2b.js, c2b_manifest.php, c2b_integrity.php, c2b_monitor.ps1 and this report generator. Final test/documentation commit is named `Finalize concurrent-user capacity verification`; its hash and final git status are supplied in the execution response to avoid a self-referential report hash.')
    (ROOT/'FINAL_CONCURRENCY_REPORT.md').write_text('\n'.join(sections),encoding='utf-8')
    print(json.dumps({'database':meta['database'],'spike':spike,'telemetry':telemetry,'integrity':'PASS','report':str(ROOT/'FINAL_CONCURRENCY_REPORT.md')},indent=2))

if __name__=='__main__':
    build()
